import { createRouter, createWebHashHistory } from 'vue-router'
import HomePage from '../components/HomePage.vue'
import AboutPage from '../components/AboutPage.vue'
import BusinessPage from '../components/BusinessPage.vue'
import WinbackPage from '../components/WinbackPage.vue'
import MainPage from '../components/MainPage.vue'
import ContactList from '../components/ContactList.vue'
import SocketComponent from '../components/SocketComponent.vue';
import listByProject from '../components/ProjectMaintenance.vue';
import saleTalk from '../components/saleTalk.vue';
import listProject from '../components/listProject.vue';
import NoteHierarchy from '../components/NoteHierarchy.vue';
import pasteProjectListing from '../components/pasteProjectListing.vue';
import importCsv from '../components/importCsv.vue';
import spreadSheet from '../components/spreadSheetIn.vue';
import spreadSheetIn2 from '../components/spreadSheetIn2.vue';
import displaySpreadsheet from '../components/spreadsheetOut.vue';
import checkDuplication from '../components/checkDuplication.vue';
import fillAllRecords from '../components/fillAllRecords.vue';

const routes = [
  {
    path: '/main',
    name: 'MainPage',
    component: MainPage,
    meta: { requiresAuth: false }
  },

  {
    path: '/cnn',
    name: 'ExternalExample',
    meta: { external: true, url: 'https://www.cnn.com' },
  },
  {
    path: '/home',
    name: 'HomePage',
    component: HomePage,
    meta: { requiresAuth: false }
  },
  {
    path: '/soc',
    name: 'SocketComponent',
    component: SocketComponent,
    meta: { requiresAuth: false }
  },

  {
    path: '/note',
    name: 'NoteHierarchy',
    component: NoteHierarchy,
    meta: { requiresAuth: false }
  },
  {
    path: '/snr',
    name: 'ContactList',
    component: ContactList,
    meta: { requiresAuth: false }
  },
  {
    path: '/',
    name: 'listByProject',
    component: listByProject,
    meta: { requiresAuth: false }
  },
  {
    path: '/talk',
    name: 'saleTalk',
    component: saleTalk,
    meta: { requiresAuth: false }
  },
  {
    path: '/listProject',
    name: 'listProject',
    component: listProject,
    meta: { requiresAuth: false }
  },
  {
    path: '/pasteProjectListing',
    name: 'pasteProjectListing',
    component: pasteProjectListing,
    meta: { requiresAuth: false }
  },
  {
    path: '/business',
    name: 'BusinessPage',
    component: BusinessPage,
    meta: { requiresAuth: false }
  },
  {
    path: '/winback',
    name: 'WinbackPage',
    component: WinbackPage,
    meta: { requiresAuth: false }
  },
  {
    path: '/about',
    name: 'AboutPage',
    component: AboutPage,
    meta: { requiresAuth: false }
  },
  {
    path: '/importCsv',
    name: 'ImportCsv',
    component: importCsv,
    meta: { requiresAuth: false }
  },

  {
    path: '/displaySpreadsheet',
    name: 'displaySpreadsheet',
    component: displaySpreadsheet,
    meta: { requiresAuth: false }
  },

  {
    path: '/spreadSheet',
    name: 'spreadSheet',
    component: spreadSheet,
    meta: { requiresAuth: false }
  },
  {
    path: '/spreadSheetIn2',
    name: 'spreadSheetIn2',
    component: spreadSheetIn2,
    meta: { requiresAuth: false }
  },

  {
    path: '/checkDuplication',
    name: 'checkDuplication',
    component: checkDuplication,
    meta: { requiresAuth: false }
  }
  ,

  {
    path: '/fillAllRecords',
    name: 'fillAllRecords',
    component: fillAllRecords,
    meta: { requiresAuth: false }
  }

]

const router = createRouter({
  history: createWebHashHistory(),
  routes
})

// Route guard
// router.beforeEach((to, from, next) => {
//   const isAuthenticated = localStorage.getItem('authenticated') === 'true';
//   if (to.matched.some(record => record.meta.requiresAuth) && !isAuthenticated) {
//     next('/');
//   } else {
//     next();
//   }
// });

router.beforeEach((to, from, next) => {
  const isAuthenticated = localStorage.getItem('authenticated') === 'true';
  if (to.matched.some(record => record.meta.requiresAuth) && !isAuthenticated) {
    next('/');
  } else if (to.meta.external) {
    window.location.href = to.meta.url; // Navigate to the external URL
  } else {
    next(); // Proceed as usual for internal routes
  }
});

export default router
