<template>
  <div>
    <table border="1" cellpadding="10" cellspacing="0">
      <thead>
        <tr>
          <th style="background-color: red; color: black;">dunt want</th>
          <th style="background-color: yellow; color: black;">no take phone</th>
          <th style="background-color: #00ff00; color: black;">can send and appointment</th>
        </tr>
        <tr>
          <th>com caller50%,closer50%</th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="contact in contacts" :key="contact.id">
          <td
            :style="getCellStyle(contact, 1)"
          >{{ contact.name }}</td>
          <td
            :style="getCellStyle(contact, 2)"
          >{{ contact.phoneNumber }}</td>
          <td
            :style="getCellStyle(contact, 3)"
          >{{ contact.email }}</td>
        </tr>
      </tbody>
    </table>
  </div>
</template>

<script>
import { loadContacts } from "../utils/contactUtils"; // Adjust the import path based on your project structure

export default {
  data() {
    return {
      contacts: [],
      projectFilter: "m_terra", // Replace with your actual project filter
    };
  },
  async mounted() {
    try {
      const allContacts = await loadContacts(this.projectFilter);
      // Only retrieve the relevant fields
      this.contacts = allContacts.map(contact => ({
        id: contact.id,
        name: contact.name,
        phoneNumber: contact.phoneNumber.replace("+","").replaceAll(" ",""),
        email: contact.email || "", // Default to empty if email doesn't exist
        status: contact.status || "", // Include status field for conditions
        rating: contact.rating || 0 // Include rating field for conditions
      }));
    } catch (error) {
      console.error("Error loading contacts:", error);
    }
  },
  methods: {
    getCellStyle(contact, column) {
      // Apply styles to the first three columns based on conditions
      if (column <= 3) {
        if (contact.status && contact.status.includes("ni")) {
          return { backgroundColor: "red", color: "black" };
        } else if (contact.status) {
          return { backgroundColor: "yellow", color: "black" };
        } else if (contact.rating === 10) {
          return { backgroundColor: "green", color: "black" };
        }
      }
      return {}; // No additional styling for other cases
    }
  }
};
</script>

<style scoped>
table, th, td {
  padding: 10px;
  text-align: left;
  border: none; /* Removes any borders */
}
</style>
