<template>
    <div>
      <h3>Set Stage to "Qualify" for All Records</h3>
      <v-btn @click="updateAllStages" :loading="loading" color="primary">
        Set Stage to "Qualify"
      </v-btn>
  
      <v-progress-linear
        v-if="loading"
        :value="progress"
        height="10"
        color="blue"
        class="my-4"
      ></v-progress-linear>
  
      <div v-if="successMessage" class="success-message">{{ successMessage }}</div>
      <div v-if="errorMessage" class="error-message">{{ errorMessage }}</div>
    </div>
  </template>
  
  <script>
  import { gql } from '@apollo/client';
  import client from '../apollo-client'; // Adjust the path to your Apollo client
  
  export default {
    name: 'SetStageToQualify',
    data() {
      return {
        loading: false,
        successMessage: '',
        errorMessage: '',
        progress: 0, // Track progress percentage
      };
    },
    methods: {
      async fetchAllRecordIds() {
        const fetchRecordsQuery = gql`
          query getAllRecords {
            leads(pagination: { limit: 10000 }) {
              data {
                id
              }
            }
          }
        `;
  
        try {
          const { data } = await client.query({
            query: fetchRecordsQuery,
          });
          return data.leads.data.map(record => record.id);
        } catch (error) {
          console.error('Error fetching all records:', error);
          throw new Error('Failed to fetch all records');
        }
      },
  
      async setStageToQualifyForAll(ids) {
        const updateStageToQualify = gql`
          mutation updateLead($id: ID!, $data: LeadInput!) {
            updateLead(id: $id, data: $data) {
              data {
                id
                attributes {
                  stage
                }
              }
            }
          }
        `;
        const updatedData = { stage: 'Qualify' };
  
        for (let i = 0; i < ids.length; i++) {
          try {
            await client.mutate({
              mutation: updateStageToQualify,
              variables: { id: ids[i], data: updatedData },
            });
            this.progress = ((i + 1) / ids.length) * 100; // Update progress
          } catch (error) {
            console.error(`Error updating lead ID ${ids[i]}:`, error);
            throw new Error('Failed to update all records');
          }
        }
      },
  
      async updateAllStages() {
        this.loading = true;
        this.successMessage = '';
        this.errorMessage = '';
        this.progress = 0;
  
        try {
          const ids = await this.fetchAllRecordIds();
          await this.setStageToQualifyForAll(ids);
          this.successMessage = 'Stage set to "Qualify" for all records successfully.';
        } catch (error) {
          this.errorMessage = 'An error occurred while updating records. Please try again.';
        } finally {
          this.loading = false;
        }
      },
    },
  };
  </script>
  
  <style scoped>
  .success-message {
    color: green;
    margin-top: 10px;
  }
  .error-message {
    color: red;
    margin-top: 10px;
  }
  </style>
  