<template>

  <div>
    <ImageSlider 
      :images="imageData"
      @image-click="handleImageClick"
    />
    <!-- Loop through the images and display caption and URL -->
    <!-- <div v-for="(image, index) in imageData" :key="index" class="image-info">
      <p>{{ image.caption }}</p>
   
    </div> -->
  </div>
</template>

<script>
import ImageSlider from './ImageSlider2.vue'

export default {
  components: { ImageSlider },
  props: {
    presentation: {
      type: Array, // Change from Object to Array
      required: true,
    },
  },
  computed: {
    imageData() {
      // Extract the image data from each item in the presentation array
      return this.presentation.flatMap((item) => 
   
        item.media.data.map((mediaItem) => ({
   
          url: mediaItem.attributes.url || '',
          alt: mediaItem.attributes.caption || 'Image',
          caption: item.caption || '',
        }))
      );
    },
  },
  methods: {
    handleImageClick(image) {
      console.log('Image clicked:', image);
    },
  },
}
</script>

<style scoped>
.image-info {
  margin-top: 10px;
}

.image-info a {
  color: blue;
  text-decoration: underline;
}
</style>
